export const html = "<style>.checkmate-copy h2.cm-h2,.checkmate-copy h2.cm-cta{font-size:26px}@media (min-width:768px){.checkmate-copy h2.cm-h2,.checkmate-copy h2.cm-cta{font-size:30px}}@media (min-width:1024px){.checkmate-copy h2.cm-h2,.checkmate-copy h2.cm-cta{font-size:36px}}.checkmate-copy h3.cm-lg{font-size:.945rem}.checkmate-copy h3.cm-xl{font-size:1.05rem}.checkmate-copy h3.cm-flow{font-size:.735rem}@media (min-width:640px){.checkmate-copy h3.cm-flow{font-size:.84rem}}@keyframes dw-rise{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}.dw-rise{animation:dw-rise .6s cubic-bezier(.21,.65,.36,1) both}@media (prefers-reduced-motion:reduce){.dw-rise{animation:none;opacity:1;transform:none}}</style><div class=\"checkmate-copy\"><section class=\"relative overflow-hidden px-5 pb-16 pt-36 sm:px-8 md:pt-44\"><div class=\"pointer-events-none absolute -right-32 -top-24 h-[480px] w-[480px] rounded-full bg-cyan/10 blur-[140px]\" aria-hidden=\"true\"></div><div class=\"pointer-events-none absolute -left-24 top-40 h-72 w-72 rounded-full bg-electric/10 blur-[120px]\" aria-hidden=\"true\"></div><div class=\"relative mx-auto grid max-w-7xl items-center gap-12 lg:grid-cols-2\"><div class=\"min-w-0\"><nav class=\"mb-6 flex flex-wrap items-center gap-2 text-xs text-white/70\" aria-label=\"Breadcrumb\"><a class=\"hover:text-cyan\" href=\"/\">Home</a><span>/</span><a class=\"hover:text-cyan\" href=\"/case-studies\">Case Studies</a><span>/</span><span class=\"text-white/70\">Person Care</span></nav><div class=\"mb-6 inline-flex rounded-2xl bg-white px-5 py-3 shadow-lg\"><div class=\"inline-flex items-center\"><img width=\"122\" height=\"53\" src=\"/case/person-care/person-care-logo.webp\" alt=\"Person Care logo\" loading=\"lazy\" decoding=\"async\" class=\"block h-10 w-auto max-w-[220px] object-contain\"></div></div><span class=\"inline-flex items-center gap-2 rounded-full border border-white/10 px-3.5 py-1.5 font-mono text-[10px] font-bold uppercase tracking-[0.22em] text-white\"><span class=\"h-1.5 w-1.5 rounded-full bg-cyan\"></span> Digital Health Platform</span><h1 class=\"mt-5 font-display text-4xl font-extrabold leading-[1.05] text-dusk sm:text-5xl\">Person Care<br><span class=\"text-gradient\">About 25–35% Less Admin Work</span></h1><p class=\"mt-6 max-w-xl text-[15px] leading-relaxed text-white/70\">A care professional should spend more time helping people, not managing software. DigiWorks AI built Person Care, a digital health platform for appointments, private communication, coaching programs, and workflow visibility.</p><div class=\"mt-8 flex flex-wrap gap-4\"><a class=\"btn-primary !px-8 !py-3.5\" href=\"/contact\">Book a Free Discovery Call <span aria-hidden=\"true\">→</span></a><a class=\"btn-ghost !px-8 !py-3.5\" href=\"/case-studies\">All Case Studies</a></div><p class=\"mt-3 text-xs text-white/70\">Free discovery session - Reply within 1 business day</p></div><div class=\"relative min-w-0\"><div class=\"overflow-hidden rounded-3xl border border-white/10 bg-ink\"><img width=\"960\" height=\"540\" src=\"/case/person-care/person-care-01.webp\" alt=\"Person Care on a tablet, laptop, and phone\" decoding=\"async\" class=\"block h-auto w-full max-w-full bg-ink object-contain\"></div></div></div></section><section class=\"relative px-6 sm:px-10\"><div class=\"dw-rise mx-auto w-full max-w-6xl px-6 sm:px-10\"><div class=\"grid grid-cols-2 gap-px overflow-hidden rounded-2xl border border-white/10 bg-dusk/10 md:grid-cols-4\"><div class=\"min-w-0 bg-ink/80 p-5\"><p class=\"font-mono text-[11px] font-semibold uppercase tracking-[0.22em] text-white/70\">Focus</p><p class=\"mt-1.5 text-sm font-semibold text-white\">Counseling · Health coaching</p></div><div class=\"min-w-0 bg-ink/80 p-5\"><p class=\"font-mono text-[11px] font-semibold uppercase tracking-[0.22em] text-white/70\">Platform</p><p class=\"mt-1.5 text-sm font-semibold text-white\">Digital health</p></div><div class=\"min-w-0 bg-ink/80 p-5\"><p class=\"font-mono text-[11px] font-semibold uppercase tracking-[0.22em] text-white/70\">Scope</p><p class=\"mt-1.5 text-sm font-semibold text-white\">Appointments, programs, communication</p></div><div class=\"min-w-0 bg-ink/80 p-5\"><p class=\"font-mono text-[11px] font-semibold uppercase tracking-[0.22em] text-white/70\">Technology</p><p class=\"mt-1.5 text-sm font-semibold text-white\">Ruby on Rails · React.js · AWS</p></div></div></div></section><section class=\"relative w-full py-16\"><div class=\"relative mx-auto w-full max-w-6xl px-6 sm:px-10\"><div class=\"text-center\"><h2 class=\"cm-h2 mt-5 font-display font-extrabold leading-[1.08] text-white\">What Person Care Changed for Care Teams</h2></div><div class=\"mt-12 grid gap-6 sm:grid-cols-2 lg:grid-cols-3\"><div class=\"dw-rise h-full\"><div class=\"glass glare relative flex h-full flex-col overflow-hidden p-7\"><p class=\"font-display text-3xl font-extrabold text-white sm:text-4xl\">25–35%</p><h3 class=\"cm-lg mt-3 font-display font-bold text-white\">Less administrative work</h3><p class=\"mt-2 text-sm leading-relaxed text-white/70\">Repetitive manual coordination moved into centralized digital workflows</p></div></div><div class=\"dw-rise h-full\"><div class=\"glass glare relative flex h-full flex-col overflow-hidden p-7\"><p class=\"font-display text-3xl font-extrabold text-white sm:text-4xl\">30–40%</p><h3 class=\"cm-lg mt-3 font-display font-bold text-white\">Less appointment coordination</h3><p class=\"mt-2 text-sm leading-relaxed text-white/70\">A structured booking workflow replaced more of the manual scheduling</p></div></div><div class=\"dw-rise h-full\"><div class=\"glass glare relative flex h-full flex-col overflow-hidden p-7\"><p class=\"font-display text-3xl font-extrabold text-white sm:text-4xl\">2–3 hrs</p><h3 class=\"cm-lg mt-3 font-display font-bold text-white\">Coaching program setup</h3><p class=\"mt-2 text-sm leading-relaxed text-white/70\">Down from around 1 day with reusable program templates</p></div></div><div class=\"dw-rise h-full\"><div class=\"glass glare relative flex h-full flex-col overflow-hidden p-7\"><p class=\"font-display text-3xl font-extrabold text-white sm:text-4xl\">40–50%</p><h3 class=\"cm-lg mt-3 font-display font-bold text-white\">Faster practitioner onboarding</h3><p class=\"mt-2 text-sm leading-relaxed text-white/70\">A standardized workflow replaced a longer setup process</p></div></div><div class=\"dw-rise h-full\"><div class=\"glass glare relative flex h-full flex-col overflow-hidden p-7\"><p class=\"font-display text-3xl font-extrabold text-white sm:text-4xl\">20–30%</p><h3 class=\"cm-lg mt-3 font-display font-bold text-white\">Less follow-up work</h3><p class=\"mt-2 text-sm leading-relaxed text-white/70\">Communication and ongoing activity stayed in one platform</p></div></div><div class=\"dw-rise h-full\"><div class=\"glass glare relative flex h-full flex-col overflow-hidden p-7\"><p class=\"font-display text-3xl font-extrabold text-white sm:text-4xl\">3x</p><h3 class=\"cm-lg mt-3 font-display font-bold text-white\">More active workflows</h3><p class=\"mt-2 text-sm leading-relaxed text-white/70\">Teams could grow without the same increase in administrative effort</p></div></div></div></div></section><section class=\"relative w-full py-16\"><div class=\"relative mx-auto w-full max-w-6xl px-6 sm:px-10\"><div class=\"mb-10\"><h2 class=\"cm-h2 mt-5 font-display font-extrabold leading-[1.08] text-white\">Before vs. After Person Care</h2></div><div class=\"overflow-x-auto\"><table class=\"w-full min-w-[44rem] border-collapse text-left text-sm\"><thead><tr class=\"font-mono text-[11px] font-semibold uppercase tracking-[0.22em] text-white/70\"><th scope=\"col\" class=\"px-4 py-3\">Area</th><th scope=\"col\" class=\"px-4 py-3\">Before</th><th scope=\"col\" class=\"px-4 py-3\">After</th><th scope=\"col\" class=\"px-4 py-3\">Business Impact</th></tr></thead><tbody><tr class=\"border-t border-white/10\"><th scope=\"row\" class=\"whitespace-nowrap px-4 py-4 font-display text-sm font-bold text-white\">Admin Work</th><td class=\"px-4 py-4 text-white/70\">Repetitive manual coordination</td><td class=\"px-4 py-4 text-white/70\">Centralized digital workflows</td><td class=\"px-4 py-4 text-white/70\">~25–35% less admin effort</td></tr><tr class=\"border-t border-white/10\"><th scope=\"row\" class=\"whitespace-nowrap px-4 py-4 font-display text-sm font-bold text-white\">Appointment Coordination</th><td class=\"px-4 py-4 text-white/70\">More manual scheduling</td><td class=\"px-4 py-4 text-white/70\">Structured booking workflow</td><td class=\"px-4 py-4 text-white/70\">~30–40% less coordination time</td></tr><tr class=\"border-t border-white/10\"><th scope=\"row\" class=\"whitespace-nowrap px-4 py-4 font-display text-sm font-bold text-white\">Program Setup</th><td class=\"px-4 py-4 text-white/70\">Around 1 day</td><td class=\"px-4 py-4 text-white/70\">Around 2–3 hours</td><td class=\"px-4 py-4 text-white/70\">Much faster setup</td></tr><tr class=\"border-t border-white/10\"><th scope=\"row\" class=\"whitespace-nowrap px-4 py-4 font-display text-sm font-bold text-white\">Practitioner Onboarding</th><td class=\"px-4 py-4 text-white/70\">Longer setup process</td><td class=\"px-4 py-4 text-white/70\">Standardized workflow</td><td class=\"px-4 py-4 text-white/70\">~40–50% faster</td></tr><tr class=\"border-t border-white/10\"><th scope=\"row\" class=\"whitespace-nowrap px-4 py-4 font-display text-sm font-bold text-white\">Client Follow-Up</th><td class=\"px-4 py-4 text-white/70\">More manual tracking</td><td class=\"px-4 py-4 text-white/70\">Centralized communication</td><td class=\"px-4 py-4 text-white/70\">~20–30% less follow-up work</td></tr><tr class=\"border-t border-white/10\"><th scope=\"row\" class=\"whitespace-nowrap px-4 py-4 font-display text-sm font-bold text-white\">Workflow Capacity</th><td class=\"px-4 py-4 text-white/70\">Growth increased admin pressure</td><td class=\"px-4 py-4 text-white/70\">Up to 3x more active workflows</td><td class=\"px-4 py-4 text-white/70\">Growth without matching admin growth</td></tr></tbody></table></div></div></section><section class=\"relative w-full py-16\"><div class=\"relative mx-auto grid w-full max-w-6xl px-6 sm:px-10 gap-12 lg:grid-cols-2\"><div class=\"min-w-0\"><h2 class=\"cm-h2 mt-5 font-display font-extrabold leading-[1.08] text-white\">The Digital Health Platform Challenge</h2><p class=\"mt-6 text-[15px] leading-relaxed text-white/70\">The problem was not one broken feature. It was the amount of repeated work around delivering care. Each new client meant appointments to coordinate. Each new coaching program could mean rebuilding the same structure again. Practitioners had to keep conversations organized and follow ongoing activity while still focusing on counseling and coaching. As the number of users and programs increased, those small administrative tasks started adding up.</p></div><div class=\"min-w-0\"><h2 class=\"cm-h2 mt-5 font-display font-extrabold leading-[1.08] text-white\">Not Another Standalone Tool</h2><p class=\"mt-6 text-[15px] leading-relaxed text-white/70\">Online counseling and health coaching involve much more than booking an appointment. Practitioners need to manage schedules, communicate with clients, prepare coaching programs, follow ongoing activity, and keep each care journey organized. When those tasks are handled through separate processes, administration starts taking time away from care. The answer was not another standalone tool. Person Care needed the main care workflows to work together.</p></div></div></section><section class=\"relative w-full py-16\"><div class=\"relative mx-auto grid w-full max-w-6xl px-6 sm:px-10 items-center gap-12 lg:grid-cols-2\"><div class=\"min-w-0\"><h2 class=\"cm-h2 mt-5 font-display font-extrabold leading-[1.08] text-white\">The Digital Health Platform</h2><p class=\"mt-6 text-[15px] leading-relaxed text-white/70\">DigiWorks AI developed one digital health platform for appointment management, private communication, structured coaching programs, and workflow visibility. Person Care needed one platform that could bring those workflows together and make growth easier to manage, without making the experience more complicated for practitioners or clients.</p></div><div class=\"min-w-0\"><div class=\"overflow-hidden rounded-3xl border border-white/10 bg-ink\"><img width=\"1024\" height=\"576\" src=\"/case/person-care/person-care-02.webp\" alt=\"Person Care counseling and health coaching screens on a tablet, laptop, and phone\" loading=\"lazy\" decoding=\"async\" class=\"block h-auto w-full max-w-full bg-ink object-contain\"></div></div></div><div class=\"relative mx-auto mt-14 w-full max-w-6xl px-6 sm:px-10\"><div class=\"grid gap-6 sm:grid-cols-2\"><div class=\"dw-rise h-full\"><div class=\"glass glare relative flex h-full flex-col p-7\"><span class=\"font-display text-3xl font-extrabold text-cyan/40\">01</span><h3 class=\"cm-xl mt-3 font-display font-bold text-white\">Appointment Management</h3><p class=\"mt-3 text-sm leading-relaxed text-white/70\">Clients and practitioners needed a simpler way to manage appointments without relying on repeated manual coordination. A structured booking workflow brought more of that process into one place. This reduced the time spent arranging and managing appointments by approximately 30–40%.</p></div></div><div class=\"dw-rise h-full\"><div class=\"glass glare relative flex h-full flex-col p-7\"><span class=\"font-display text-3xl font-extrabold text-cyan/40\">02</span><h3 class=\"cm-xl mt-3 font-display font-bold text-white\">Private Client Communication</h3><p class=\"mt-3 text-sm leading-relaxed text-white/70\">Care does not stop when a scheduled session ends. Person Care provided a dedicated environment for communication between clients and practitioners. Keeping communication inside the platform made ongoing client activity easier to manage instead of spreading conversations across disconnected channels.</p></div></div><div class=\"dw-rise h-full\"><div class=\"glass glare relative flex h-full flex-col p-7\"><span class=\"font-display text-3xl font-extrabold text-cyan/40\">03</span><h3 class=\"cm-xl mt-3 font-display font-bold text-white\">Structured Coaching Programs</h3><p class=\"mt-3 text-sm leading-relaxed text-white/70\">Each new coaching program could mean rebuilding similar plans and structures by hand. Reusable coaching program templates reduced that repetition. A process that could take close to one working day could instead be completed in roughly 2–3 hours.</p></div></div><div class=\"dw-rise h-full\"><div class=\"glass glare relative flex h-full flex-col p-7\"><span class=\"font-display text-3xl font-extrabold text-cyan/40\">04</span><h3 class=\"cm-xl mt-3 font-display font-bold text-white\">Clearer Workflow Visibility</h3><p class=\"mt-3 text-sm leading-relaxed text-white/70\">As more appointments, clients, and programs became active, practitioners needed a clearer picture of what required attention. Dashboards brought key activity into one place. That visibility helped teams manage more active workflows without increasing administrative work at the same rate.</p></div></div></div></div></section><section class=\"relative w-full py-16\"><div class=\"relative mx-auto w-full max-w-6xl px-6 sm:px-10\"><h2 class=\"cm-h2 mt-5 font-display font-extrabold leading-[1.08] text-white\">What DigiWorks AI Custom Built</h2><p class=\"mt-6 max-w-3xl text-[15px] leading-relaxed text-white/70\">Each technology had a clear role. React.js supported the user-facing platform. Ruby on Rails handled the core workflows. AWS provided the cloud foundation. The stack was not the story by itself. Its value came from supporting a platform that could handle more activity without making everyday workflows harder to manage. For a broader build, custom software development services can shape a platform around a real care workflow.</p><div class=\"mt-8 flex flex-wrap gap-2.5\"><span class=\"rounded-full border border-white/10 px-3.5 py-1.5 font-mono text-[10px] font-bold uppercase tracking-[0.22em] text-white/80\">Appointment management</span><span class=\"rounded-full border border-white/10 px-3.5 py-1.5 font-mono text-[10px] font-bold uppercase tracking-[0.22em] text-white/80\">Private client communication</span><span class=\"rounded-full border border-white/10 px-3.5 py-1.5 font-mono text-[10px] font-bold uppercase tracking-[0.22em] text-white/80\">Structured coaching programs</span><span class=\"rounded-full border border-white/10 px-3.5 py-1.5 font-mono text-[10px] font-bold uppercase tracking-[0.22em] text-white/80\">Reusable program templates</span><span class=\"rounded-full border border-white/10 px-3.5 py-1.5 font-mono text-[10px] font-bold uppercase tracking-[0.22em] text-white/80\">Workflow dashboards</span><span class=\"rounded-full border border-white/10 px-3.5 py-1.5 font-mono text-[10px] font-bold uppercase tracking-[0.22em] text-white/80\">Practitioner onboarding</span><span class=\"rounded-full border border-white/10 px-3.5 py-1.5 font-mono text-[10px] font-bold uppercase tracking-[0.22em] text-white/80\">Client follow-up</span><span class=\"rounded-full border border-white/10 px-3.5 py-1.5 font-mono text-[10px] font-bold uppercase tracking-[0.22em] text-white/80\">React.js frontend</span><span class=\"rounded-full border border-white/10 px-3.5 py-1.5 font-mono text-[10px] font-bold uppercase tracking-[0.22em] text-white/80\">Ruby on Rails backend</span><span class=\"rounded-full border border-white/10 px-3.5 py-1.5 font-mono text-[10px] font-bold uppercase tracking-[0.22em] text-white/80\">AWS cloud infrastructure</span></div><div class=\"mt-10 grid gap-6 md:grid-cols-3\"><div class=\"dw-rise h-full\"><div class=\"glass glare relative h-full p-7\"><h3 class=\"cm-xl font-display font-bold text-white\">React.js Frontend</h3><p class=\"mt-3 text-sm leading-relaxed text-white/70\">React.js supported the user-facing platform and responsive workflows for appointments, dashboards, and ongoing interaction.</p></div></div><div class=\"dw-rise h-full\"><div class=\"glass glare relative h-full p-7\"><h3 class=\"cm-xl font-display font-bold text-white\">Ruby on Rails Backend</h3><p class=\"mt-3 text-sm leading-relaxed text-white/70\">Ruby on Rails handled the backend logic behind booking, coaching programs, user workflows, and core application operations.</p></div></div><div class=\"dw-rise h-full\"><div class=\"glass glare relative h-full p-7\"><h3 class=\"cm-xl font-display font-bold text-white\">AWS Cloud Infrastructure</h3><p class=\"mt-3 text-sm leading-relaxed text-white/70\">AWS provided the cloud foundation needed to support increasing platform activity and continued product growth.</p></div></div></div></div></section><section class=\"relative w-full py-16\"><div class=\"relative mx-auto grid w-full max-w-6xl px-6 sm:px-10 items-center gap-12 lg:grid-cols-2\"><div class=\"min-w-0\"><div class=\"overflow-hidden rounded-3xl border border-white/10 bg-ink\"><img width=\"1024\" height=\"576\" src=\"/case/person-care/person-care-03.webp\" alt=\"Person Care on a laptop, tablet, and phone\" loading=\"lazy\" decoding=\"async\" class=\"block h-auto w-full max-w-full bg-ink object-contain\"></div></div><div class=\"min-w-0\"><h2 class=\"cm-h2 mt-5 font-display font-extrabold leading-[1.08] text-white\">Why Person Care Could Support 3x More Workflows</h2><ul class=\"mt-6 space-y-3.5\"><li class=\"relative pl-7 text-[15px] leading-relaxed text-white/70\"><span class=\"absolute left-0 top-[9px] h-2 w-2 rounded-sm bg-cyan\" aria-hidden=\"true\"></span>The increase in capacity did not come from asking practitioners to work faster.</li><li class=\"relative pl-7 text-[15px] leading-relaxed text-white/70\"><span class=\"absolute left-0 top-[9px] h-2 w-2 rounded-sm bg-cyan\" aria-hidden=\"true\"></span>It came from reducing repeated work around care delivery.</li><li class=\"relative pl-7 text-[15px] leading-relaxed text-white/70\"><span class=\"absolute left-0 top-[9px] h-2 w-2 rounded-sm bg-cyan\" aria-hidden=\"true\"></span>Booking became more structured, and program templates reduced repeated setup.</li><li class=\"relative pl-7 text-[15px] leading-relaxed text-white/70\"><span class=\"absolute left-0 top-[9px] h-2 w-2 rounded-sm bg-cyan\" aria-hidden=\"true\"></span>Communication stayed inside the platform, and dashboards made ongoing activity easier to follow.</li><li class=\"relative pl-7 text-[15px] leading-relaxed text-white/70\"><span class=\"absolute left-0 top-[9px] h-2 w-2 rounded-sm bg-cyan\" aria-hidden=\"true\"></span>Teams could manage up to 3x more active workflows without the same 3x increase in coordination and administrative effort.</li></ul></div></div></section><section class=\"relative w-full py-16\"><div class=\"relative mx-auto w-full max-w-6xl px-6 sm:px-10\"><div class=\"mx-auto max-w-3xl text-center\"><h2 class=\"cm-h2 mt-5 font-display font-extrabold leading-[1.08] text-white\">Why This Project Worked</h2></div><p class=\"mx-auto mt-6 max-w-3xl text-center text-[15px] leading-relaxed text-white/70\">Person Care did not try to solve every healthcare technology problem. It focused on the work practitioners had to repeat every day. Instead of adding more technology around care, the platform reduced the amount of technology practitioners had to think about.</p><div class=\"mt-12 grid gap-6 md:grid-cols-3\"><div class=\"dw-rise h-full\"><div class=\"glass glare relative h-full p-7\"><h3 class=\"cm-xl font-display font-bold text-white\">Easier Appointments</h3><p class=\"mt-3 text-sm leading-relaxed text-white/70\">Appointments became easier to coordinate. Booking became more structured, so less of that work stayed manual.</p></div></div><div class=\"dw-rise h-full\"><div class=\"glass glare relative h-full p-7\"><h3 class=\"cm-xl font-display font-bold text-white\">Faster Programs</h3><p class=\"mt-3 text-sm leading-relaxed text-white/70\">Programs became faster to prepare. Reusable templates cut setup from around one working day to roughly 2–3 hours.</p></div></div><div class=\"dw-rise h-full\"><div class=\"glass glare relative h-full p-7\"><h3 class=\"cm-xl font-display font-bold text-white\">Organized Communication</h3><p class=\"mt-3 text-sm leading-relaxed text-white/70\">Client communication stayed organized, and ongoing workflows became easier to see from one place.</p></div></div></div></div></section><section class=\"relative w-full py-16\"><div class=\"relative mx-auto w-full max-w-3xl px-6 sm:px-10 text-center\"><h2 class=\"cm-h2 mt-5 font-display font-extrabold leading-[1.08] text-white\">A Practical Approach to AI</h2><p class=\"mt-6 text-[15px] leading-relaxed text-white/70\">AI should not be added just because it is available. Person Care’s immediate problem was workflow management, not machine learning. The right first step was building a stable digital health platform around real practitioner and client needs. If future features genuinely require machine learning, <a class=\"font-medium text-white underline decoration-coral/40 underline-offset-2 hover:text-coral\" href=\"/services/mlops-setup\">MLOps</a> can support reliable deployment, monitoring, and operation at that stage. The technology should follow a real use case, not be forced into the product simply to claim an AI feature.</p></div></section><section class=\"relative w-full py-16\"><div class=\"relative mx-auto w-full max-w-6xl px-6 sm:px-10\"><div class=\"mx-auto max-w-3xl text-center\"><h2 class=\"cm-h2 mt-5 font-display font-extrabold leading-[1.08] text-white\">Keep exploring</h2></div><div class=\"mt-12 grid gap-6 md:grid-cols-3\"><div class=\"dw-rise\"><a class=\"group block\" href=\"/case-studies/checkmate\"><div class=\"glass h-full overflow-hidden transition-colors hover:!border-cyan/40\"><div class=\"relative h-36 overflow-hidden\"><img width=\"1200\" height=\"675\" src=\"/case/checkmate/checkmate-01.webp\" alt=\"Checkmate\" loading=\"lazy\" class=\"h-full w-full object-cover transition-transform duration-700 group-hover:scale-105\"><div class=\"absolute inset-0 bg-gradient-to-t from-cyan to-electric opacity-25 mix-blend-multiply\"></div></div><div class=\"p-6\"><div class=\"h-1 w-12 rounded-full bg-gradient-to-r from-cyan to-electric\"></div><h3 class=\"cm-lg mt-3 font-display font-bold text-white\">Checkmate</h3><p class=\"mt-1 text-sm text-white/70\">Doubled Peak-Hour Order Capacity</p></div></div></a></div><div class=\"dw-rise\"><a class=\"group block\" href=\"/case-studies/lead-scout\"><div class=\"glass h-full overflow-hidden transition-colors hover:!border-cyan/40\"><div class=\"relative h-36 overflow-hidden\"><img width=\"1200\" height=\"675\" src=\"/case/lead-scout/lead-scout-01.webp\" alt=\"Lead Scout\" loading=\"lazy\" class=\"h-full w-full object-cover transition-transform duration-700 group-hover:scale-105\"><div class=\"absolute inset-0 bg-gradient-to-t from-cyan to-electric opacity-25 mix-blend-multiply\"></div></div><div class=\"p-6\"><div class=\"h-1 w-12 rounded-full bg-gradient-to-r from-cyan to-electric\"></div><h3 class=\"cm-lg mt-3 font-display font-bold text-white\">Lead Scout</h3><p class=\"mt-1 text-sm text-white/70\">About 35–40% Less Research Time</p></div></div></a></div><div class=\"dw-rise\"><a class=\"group block\" href=\"/case-studies/orange-ruler\"><div class=\"glass h-full overflow-hidden transition-colors hover:!border-cyan/40\"><div class=\"relative h-36 overflow-hidden\"><img width=\"1200\" height=\"675\" src=\"/case/orange-ruler/orange-ruler-01.webp\" alt=\"Orange Ruler\" loading=\"lazy\" class=\"h-full w-full object-cover transition-transform duration-700 group-hover:scale-105\"><div class=\"absolute inset-0 bg-gradient-to-t from-cyan to-electric opacity-25 mix-blend-multiply\"></div></div><div class=\"p-6\"><div class=\"h-1 w-12 rounded-full bg-gradient-to-r from-cyan to-electric\"></div><h3 class=\"cm-lg mt-3 font-display font-bold text-white\">Orange Ruler</h3><p class=\"mt-1 text-sm text-white/70\">About 80% Faster Campaign Setup</p></div></div></a></div></div></div></section><section class=\"relative overflow-hidden px-6 py-16 sm:px-10\"><div class=\"relative mx-auto max-w-3xl text-center\"><h2 class=\"cm-cta font-display font-extrabold leading-[1.08] text-white\">Build a Scalable Digital Health Platform</h2><p class=\"mx-auto mt-6 max-w-xl text-[15px] leading-relaxed text-white/70\">Digital health software should reduce work for care teams, not create another system they have to manage. DigiWorks AI’s custom software development services help businesses build scalable platforms around real workflows, users, and operational requirements. If your counseling, coaching, or digital health product is becoming harder to manage as usage grows, we can help turn disconnected workflows into one scalable platform.</p><div class=\"mt-10 flex flex-wrap items-center justify-center gap-4\"><a class=\"btn-primary !px-9 !py-4 !text-base\" href=\"/contact\">Build a Scalable Digital Health Platform <span aria-hidden=\"true\">→</span></a><a class=\"btn-ghost !px-8 !py-3.5\" href=\"/case-studies\">All Case Studies</a></div><p class=\"mt-4 text-xs text-white/70\">Free discovery session - Reply within 1 business day</p></div></section></div>";
